const fs = require('fs');

const d = {
    "C": 0, "C#": 1, "D": 2, "D#": 3, "E": 4,
    "F": 5, "F#": 6, "G": 7, "G#": 8, "A": 9,
    "B": 10, "H": 11
};

function chrd(x, y, z) {
    const a = (d[y] - d[x] + 12) % 12;
    const b = (d[z] - d[y] + 12) % 12;
    if (a === 4 && b === 3) return "major";
    if (a === 3 && b === 4) return "minor";
    return "0";
}

const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
const [x, y, z] = input;

const perms = [
    [x, y, z], [x, z, y],
    [y, x, z], [y, z, x],
    [z, x, y], [z, y, x]
];

for (const [a, b, c] of perms) {
    const res = chrd(a, b, c);
    if (res !== "0") {
        console.log(res);
        process.exit(0);
    }
}
console.log("strange");

